**label.go**

```go
package lesson

func Label(value int) string {
	if value < 0 {
		return "negative"
	}
	if value == 0 {
		return "zero"
	}
	return "positive"
}
```

**label_test.go**

```go
package lesson

import "testing"

func TestLabel(t *testing.T) {
	if got := Label(0); got != "zero" {
		t.Errorf("Label(0) = %q; want zero", got)
	}
	if got := Label(2); got != "positive" {
		t.Errorf("Label(2) = %q; want positive", got)
	}
}
```

**Run it**

```bash
go test -cover ./...
```

The command reveals that some statements were not executed. It cannot decide whether the missing negative case matters to the product contract.

**numbers.go**

```go
package lesson

func Abs(value int) int {
	if value < 0 {
		return -value
	}
	return value
}

func Lookup(values map[string]int, key string) (int, bool) {
	value, ok := values[key]
	return value, ok
}
```

**numbers_test.go**

```go
package lesson

import "testing"

func TestAbs(t *testing.T) {
	for input, want := range map[int]int{-4: 4, 0: 0, 3: 3} {
		if got := Abs(input); got != want {
			t.Errorf("Abs(%d) = %d; want %d", input, got, want)
		}
	}
}

func TestLookupFound(t *testing.T) {
	value, ok := Lookup(map[string]int{"ready": 1}, "ready")
	if !ok || value != 1 {
		t.Fatalf("Lookup = (%d, %v); want (1, true)", value, ok)
	}
}
```

**Run it**

```bash
go test -coverprofile=coverage.out ./...
go tool cover -func=coverage.out
go tool cover -html=coverage.out -o coverage.html
```

The text and HTML reports use the same generated profile, so the total, function view, and source view describe one reproducible test action.
